// ── Aggregate SF Products ──────────────────────────────────────────
// Input 0: OLI records from SF SOQL (accounts with 0 purchases still arrive due to alwaysOutputData)
// Input 1: ERP catalog from HTTP node

const oliRecords = $input.all();

// Safely read ERP catalog from its node
let erpRaw = {};
try { erpRaw = $('HTTP - ERP Product Catalog').first().json; } catch(e) {}

// Parse ERP catalog
const erpProducts = (erpRaw.products || []).map(p => ({
  name: p.title || p.name || '',
  price: parseFloat(p.price || 0)
})).filter(p => p.name);

// Parse SF purchased products
const purchased = {};
let totalSpend = 0;
for (const rec of oliRecords) {
  // Handle both nested and flat Salesforce SOQL response shapes
  const name = rec.json?.Product2?.Name
    || rec.json?.['Product2.Name']
    || rec.json?.productName
    || '';
  if (!name) continue;
  if (!purchased[name]) purchased[name] = { qty: 0, spend: 0 };
  purchased[name].qty  += parseFloat(rec.json.Quantity  || 0);
  purchased[name].spend += parseFloat(rec.json.TotalPrice || 0);
  totalSpend += parseFloat(rec.json.TotalPrice || 0);
}

const purchasedNames = Object.keys(purchased);
const purchasedSet   = new Set(purchasedNames.map(n => n.toLowerCase()));

// White space = ERP catalog MINUS what this account already bought
const whiteSpaceProducts = erpProducts.filter(p => !purchasedSet.has(p.name.toLowerCase()));

// Metrics
const avgPerProduct = purchasedNames.length > 0 ? totalSpend / purchasedNames.length : 0;
const estimatedWsv  = Math.round(avgPerProduct * whiteSpaceProducts.length);
const totalProducts = purchasedNames.length + whiteSpaceProducts.length;
const penetrationPct = totalProducts > 0
  ? Math.round((purchasedNames.length / totalProducts) * 100) : 0;

let tier = 'Low';
if (estimatedWsv > 500000 || whiteSpaceProducts.length > 20) tier = 'High';
else if (estimatedWsv > 100000 || whiteSpaceProducts.length > 8)  tier = 'Medium';

// Pull account fields from SplitInBatches (the source of truth for the current account)
let sf = {};
try { sf = $('SplitInBatches').first().json; } catch(e) {}

const ownerName  = sf['Owner.Name']  || sf?.Owner?.Name  || '';
const ownerEmail = sf['Owner.Email'] || sf?.Owner?.Email || '';

// Build rich LLM context string
const ctx = [
  `ACCOUNT: ${sf.Name} (ID: ${sf.Id})`,
  `Industry: ${sf.Industry || 'N/A'} | Revenue: $${(sf.AnnualRevenue||0).toLocaleString()} | Employees: ${sf.NumberOfEmployees || 'N/A'} | Country: ${sf.BillingCountry || 'N/A'}`,
  `Owner: ${ownerName} <${ownerEmail}>`,
  '',
  `PRODUCTS ALREADY PURCHASED (${purchasedNames.length}):`,
  purchasedNames.length > 0
    ? purchasedNames.map(n => `  - ${n}: qty ${purchased[n].qty}, spend $${purchased[n].spend.toLocaleString()}`).join('\n')
    : '  None on record',
  '',
  `WHITE SPACE — PRODUCTS NOT YET PURCHASED (${whiteSpaceProducts.length}):`,
  whiteSpaceProducts.length > 0
    ? whiteSpaceProducts.slice(0, 20).map(p => `  - ${p.name} (catalog price: $${p.price.toLocaleString()})`).join('\n')
    : '  None — account has full coverage',
  whiteSpaceProducts.length > 20 ? `  ... and ${whiteSpaceProducts.length - 20} more` : '',
  '',
  'METRICS',
  `  Total SF Spend (Closed Won):  $${totalSpend.toLocaleString()}`,
  `  Product Penetration Rate:     ${penetrationPct}%`,
  `  Catalog Coverage:             ${purchasedNames.length} of ${totalProducts} products`,
  `  Est. White Space Value:       $${estimatedWsv.toLocaleString()}`,
  `  Priority Tier:                ${tier}`,
].join('\n');

return [{
  json: {
    account_id:                sf.Id           || '',
    account_name:              sf.Name         || '',
    industry:                  sf.Industry     || '',
    annual_revenue:            sf.AnnualRevenue || 0,
    billing_country:           sf.BillingCountry || '',
    owner_name:                ownerName,
    owner_email:               ownerEmail,
    products_purchased:        purchasedNames,
    products_purchased_detail: purchased,
    products_not_purchased:    whiteSpaceProducts.map(p => p.name),
    white_space_detail:        whiteSpaceProducts,
    total_spend:               totalSpend,
    estimated_white_space_value: estimatedWsv,
    penetration_rate_pct:      penetrationPct,
    priority_tier:             tier,
    context_summary:           ctx
  }
}];

// ── Filter Fresh Accounts ──────────────────────────────────────────
// FIX: This node handles THREE cases safely:
//   1. Sheet is EMPTY (0 rows)        → treat as no processed accounts → always proceed
//   2. Sheet has rows, account NOT in it this week → proceed
//   3. Sheet has rows, account already processed this week → skip (return [])

const getISOWeek = (date) => {
  const d = new Date(date);
  const day = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - day);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  const weekNo = Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
  return `${d.getUTCFullYear()}-W${String(weekNo).padStart(2, '0')}`;
};

const currentWeek = getISOWeek(new Date());

// $input.all() safely returns [] when the sheet is empty — no crash
const sheetRows = $input.all();

// Build set of account IDs already processed THIS week
const processedThisWeek = new Set(
  sheetRows
    .filter(r => r.json && r.json.processed_week === currentWeek)
    .map(r => String(r.json.account_id || '').trim())
    .filter(Boolean)
);

// Get the current account data from Aggregate node
let accountData;
try {
  accountData = $('Aggregate SF Products').first();
} catch(e) {
  // If Aggregate node has no data, skip gracefully
  console.log('[FilterFresh] Could not read Aggregate SF Products, skipping.');
  return [];
}

if (!accountData || !accountData.json) {
  console.log('[FilterFresh] No account data found, skipping.');
  return [];
}

const accId = String(accountData.json.account_id || '').trim();

if (!accId) {
  console.log('[FilterFresh] Account ID is empty, skipping.');
  return [];
}

if (processedThisWeek.has(accId)) {
  console.log(`[Dedup] Skipping ${accId} (${accountData.json.account_name}) — already processed in ${currentWeek}`);
  return [];
}

console.log(`[FilterFresh] Processing ${accId} (${accountData.json.account_name}) for week ${currentWeek}. Sheet had ${sheetRows.length} row(s).`);

return [{ json: { ...accountData.json, current_week: currentWeek } }];

// ── Parse JSON - LLM Response ──────────────────────────────────────
// Handles all Gemini/LLM response shapes and merges with account context

const items = $input.all();
const results = [];

for (const item of items) {
  let rawText = '';

  // Extract text from every possible response shape
  if (typeof item.json?.text === 'string') {
    rawText = item.json.text;
  } else if (item.json?.message?.content) {
    rawText = item.json.message.content;
  } else if (item.json?.choices?.[0]?.message?.content) {
    rawText = item.json.choices[0].message.content;
  } else if (item.json?.candidates?.[0]?.content?.parts?.[0]?.text) {
    // Native Gemini REST shape
    rawText = item.json.candidates[0].content.parts[0].text;
  } else if (item.json?.content) {
    rawText = typeof item.json.content === 'string'
      ? item.json.content
      : JSON.stringify(item.json.content);
  } else {
    rawText = JSON.stringify(item.json);
  }

  // Strip markdown fences (Gemini sometimes adds them despite instructions)
  rawText = rawText
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let parsed = {};
  let parseError = false;

  try {
    parsed = JSON.parse(rawText);
  } catch (e) {
    parseError = true;
    console.error('[ParseJSON] Failed:', e.message);
    console.error('[ParseJSON] Raw (first 600 chars):', rawText.substring(0, 600));
  }

  // Get upstream account context
  let accountCtx = {};
  try {
    accountCtx = $('Filter Fresh Accounts').first().json;
  } catch(e) {
    try { accountCtx = $('Aggregate SF Products').first().json; } catch(e2) {}
  }

  const opp  = Array.isArray(parsed.top_opportunities) ? parsed.top_opportunities : [];
  const opp1 = opp[0] || {};
  const opp2 = opp[1] || {};
  const opp3 = opp[2] || {};

  const tierMap = { 'High': 'High', 'Medium': 'Normal', 'Low': 'Low' };
  const sfPriority = tierMap[parsed.priority_tier || accountCtx.priority_tier] || 'Normal';

  const activityDate = new Date();
  activityDate.setDate(activityDate.getDate() + 7);
  const activityDateStr = activityDate.toISOString().split('T')[0];

  results.push({
    json: {
      _parse_error: parseError,
      _raw_llm_output: parseError ? rawText.substring(0, 1000) : undefined,

      // AI output
      priority_tier:              parsed.priority_tier              || accountCtx.priority_tier || 'Low',
      white_space_summary:        parsed.white_space_summary        || '',
      top_opportunities:          opp,
      competitor_risk:            parsed.competitor_risk            || 'None',
      competitor_notes:           parsed.competitor_notes           || '',
      recommended_next_action:    parsed.recommended_next_action    || '',
      suggested_task_subject:     (parsed.suggested_task_subject    || 'White Space Follow-Up: ' + (accountCtx.account_name || '')).substring(0, 80),
      suggested_task_description: parsed.suggested_task_description || '',
      email_subject:              parsed.email_subject              || `White Space Opportunity: ${accountCtx.account_name || ''}`,
      email_body:                 parsed.email_body                 || '',
      sf_priority:                sfPriority,
      activity_date:              activityDateStr,

      // Flat opportunity columns for Sheets
      opp_1_title:      opp1.opportunity_title   || '',
      opp_1_product:    opp1.product_name        || '',
      opp_1_value:      opp1.estimated_value_usd || 0,
      opp_1_urgency:    opp1.urgency             || '',
      opp_1_confidence: opp1.confidence_score    || 0,
      opp_2_title:      opp2.opportunity_title   || '',
      opp_2_product:    opp2.product_name        || '',
      opp_2_value:      opp2.estimated_value_usd || 0,
      opp_3_title:      opp3.opportunity_title   || '',
      opp_3_product:    opp3.product_name        || '',
      opp_3_value:      opp3.estimated_value_usd || 0,

      // Pass-through account fields
      account_id:                accountCtx.account_id                || '',
      account_name:              accountCtx.account_name              || '',
      industry:                  accountCtx.industry                  || '',
      annual_revenue:            accountCtx.annual_revenue            || 0,
      billing_country:           accountCtx.billing_country           || '',
      owner_name:                accountCtx.owner_name                || '',
      owner_email:               accountCtx.owner_email               || '',
      penetration_rate_pct:      accountCtx.penetration_rate_pct      || 0,
      est_white_space_value_usd: accountCtx.estimated_white_space_value || 0,
      total_spend:               accountCtx.total_spend               || 0,
      current_week:              accountCtx.current_week              || ''
    }
  });
}

return results;

// ── Error Logger ───────────────────────────────────────────────────
// Logs parse failures and continues the loop cleanly
const item = $input.first();
const accountId   = item.json.account_id   || 'unknown';
const accountName = item.json.account_name || 'unknown';
const rawOutput   = item.json._raw_llm_output || '';

console.error(`[ERROR] LLM parse failed — Account: ${accountName} (${accountId})`);
console.error(`[ERROR] Raw output preview: ${rawOutput}`);

// Return an item so SplitInBatches always gets output and can loop to next account
return [{
  json: {
    error_logged:        true,
    account_id:          accountId,
    account_name:        accountName,
    error_reason:        'LLM JSON parse failed',
    raw_output_preview:  rawOutput.substring(0, 500),
    logged_at:           new Date().toISOString()
  }
}];
